from taf.gnb.oam.coam.cu.schemas.base import SchemaField, SchemaObject


class AffectedCells(SchemaObject):
    faulty_cells = SchemaField(name="faultyCells")
    degraded_cells = SchemaField(name="degradedCells")

    def __init__(self, faulty_cells, degraded_cells):
        self.faulty_cells = faulty_cells
        self.degraded_cells = degraded_cells
        super(AffectedCells, self).__init__()


class HistoricalAlarmsSlot(SchemaObject):
    uuid = SchemaField(name="uuid")
    severity = SchemaField(name="severity")
    alarm_id = SchemaField(name="alarmId")
    alarm_name = SchemaField(name="alarmName")
    fault_id = SchemaField(name="faultId")
    fault_name = SchemaField(name="faultName")
    alarming_object = SchemaField(name="alarmingObject")
    appear_time = SchemaField(name="appearTime")
    last_updated_time = SchemaField(name="lastUpdatedTime")
    affected_cells = SchemaField(name='affectedCells', klass=AffectedCells)
    probable_cause_name = SchemaField(name="probableCauseName")
    additional_info = SchemaField(name="additionalInfo")
    event_type_name = SchemaField(name="eventTypeName")
    cleared_time = SchemaField(name="clearedTime")

    def __init__(self, uuid, severity, alarm_id, alarm_name, fault_id, fault_name, alarming_object, appear_time,
                 affected_cells, last_updated_time, probable_cause_name, additional_info, event_type_name, cleared_time):
        self.uuid = uuid
        self.severity = severity
        self.alarm_id = alarm_id
        self.alarm_name = alarm_name
        self.fault_id = fault_id
        self.fault_name = fault_name
        self.alarming_object = alarming_object
        self.appear_time = appear_time
        self.affected_cells = affected_cells
        self.last_updated_time = last_updated_time
        self.probable_cause_name = probable_cause_name
        self.additional_info = additional_info
        self.event_type_name = event_type_name
        self.cleared_time = cleared_time

        super(HistoricalAlarmsSlot, self).__init__()


class HistoricalAlarmsV1(SchemaObject):
    total = SchemaField(name="total")
    alarms = SchemaField(name="alarms", klass=HistoricalAlarmsSlot, many=True)

    def __init__(self, total, alarms):
        self.total = total
        if alarms:
            self.alarms = alarms
        else:
            self.alarms = []

        super(HistoricalAlarmsV1, self).__init__()
